function icon(
  parent,
  name,
  x,
  y,
  size,
  iconColor = C.forest,
  strokeWidth = 1.8,
) {
  const adjustedStroke =
    name === "back" || name === "chevron"
      ? Math.max(strokeWidth, 2.2)
      : strokeWidth;
  const node = figma.createVector();
  node.name = `Icon/${name}`;
  node.vectorPaths = [
    {
      windingRule: "NONZERO",
      data: ICON_PATHS[name] || ICON_PATHS.star,
    },
  ];
  node.resize(size, size);
  node.fills = [];
  node.strokes = [solid(iconColor)];
  node.strokeWeight = adjustedStroke;
  node.strokeCap = "ROUND";
  node.strokeJoin = "ROUND";
  append(parent, node);
  node.x = x;
  node.y = y;
  return node;
}

function pill(
  parent,
  label,
  x,
  y,
  width,
  fill = C.paper,
  textColor = C.forestSoft,
  height = 28,
) {
  const node = frame(parent, `标签/${label}`, x, y, width, height, fill, height / 2);
  text(node, label, 10, (height - 14) / 2, width - 20, {
    size: 10,
    color: textColor,
    weight: "medium",
    align: "CENTER",
    lineHeight: 14,
  });
  return node;
}

