function buildBookDataScreens() {
  const detailsX = 48;
  const detailsY = 4300;
  const gapX = 430;
  const gapY = 930;
  BOOK_DATA.books.forEach((book, index) => {
    const col = index % 4;
    const row = Math.floor(index / 4);
    buildDataBookDetail(
      book,
      detailsX + col * gapX,
      detailsY + row * gapY,
    );
  });

  const readersY = detailsY + Math.ceil(BOOK_DATA.books.length / 4) * gapY + 500;
  const allPages = [];
  for (const book of BOOK_DATA.books) {
    for (const page of book.pages) allPages.push({ book, page });
  }
  allPages.forEach(({ book, page }, index) => {
    const col = index % 4;
    const row = Math.floor(index / 4);
    buildDataBookReader(
      book,
      page,
      detailsX + col * gapX,
      readersY + row * gapY,
    );
  });

  const audioY = readersY + Math.ceil(allPages.length / 4) * gapY + 500;
  BOOK_DATA.books.forEach((book, index) => {
    const col = index % 4;
    const row = Math.floor(index / 4);
    buildDataBookAudio(
      book,
      detailsX + col * gapX,
      audioY + row * gapY,
    );
  });
}

