async function attachFlow(frames) {
  const transitions = {
    home: frames.home,
    library: frames.library,
    detail: frames.detail,
    reader: frames.reader,
    readerPlaying: frames.readerPlaying,
    ai: frames.ai,
    aiAnswer: frames.aiAnswer,
    summary: frames.summary,
    growth: frames.growth,
    original: frames.original,
    originalDraft: frames.originalDraft,
    parent: frames.parent,
    search: frames.search,
    shelf: frames.shelf,
    adminList: frames.adminList,
    adminReview: frames.adminReview,
    adminDashboard: frames.adminDashboard,
    adminKnowledge: frames.adminKnowledge,
    adminPermissions: frames.adminPermissions,
  };
  Object.assign(transitions, BOOK_FRAME_MAP);

  for (const { node, destination } of FLOW_LINKS) {
    const target = transitions[destination];
    if (!target) continue;
    try {
      await node.setReactionsAsync([
        {
          trigger: { type: "ON_CLICK" },
          actions: [
            {
              type: "NODE",
              destinationId: target.id,
              navigation: "NAVIGATE",
              transition: null,
              preserveScrollPosition: false,
            },
          ],
        },
      ]);
    } catch (error) {
      console.warn("Failed to attach reaction", destination, error);
    }
  }

  PAGES.mobile.selection = [frames.home];
}

