function removeEmptyDefaultPages() {
  const pluginPages = new Set(Object.values(PAGES));
  for (const page of [...figma.root.children]) {
    if (pluginPages.has(page)) continue;
    if (page.children.length > 0) continue;
    if (page.name === "Page 1" || page.name === "页面 1") {
      page.remove();
    }
  }
}

async function main() {
  await figma.loadAllPagesAsync();
  removeDuplicateGeneratedPages();
  await loadFonts();
  await createImageAssets();
  await loadBookCoverImages();

  PAGES.design = await getPluginPage("00 知芽 · 设计规范", 0);
  PAGES.mobile = await getPluginPage("01 知芽 · 移动端原型", 1);
  PAGES.components = await getPluginPage("02 知芽 · 组件与状态", 2);
  PAGES.flow = await getPluginPage("03 知芽 · 原型流程", 3);
  PAGES.admin = await getPluginPage("04 知芽 · 后台管理原型", 4);
  removeEmptyDefaultPages();

  buildDesignPage();
  COMPONENTS = await buildComponentsPage();
  const frames = await buildMobilePages(COMPONENTS);
  buildBookDataScreens();
  const adminFrames = buildAdminPage();
  frames.adminDashboard = adminFrames.dashboard;
  frames.adminList = adminFrames.list;
  frames.adminReview = adminFrames.review;
  frames.adminKnowledge = adminFrames.knowledge;
  frames.adminPermissions = adminFrames.permissions;
  await figma.setCurrentPageAsync(PAGES.mobile);
  await attachFlow(frames);
  buildFlowPage(frames);

  await figma.setCurrentPageAsync(PAGES.mobile);
  figma.viewport.scrollAndZoomIntoView(Object.values(frames));
  figma.notify("知芽移动端原型已生成：8 个页面、组件和基础连线。", {
    timeout: 5000,
  });
  figma.closePlugin();
}

main().catch((error) => {
  console.error(error);
  figma.notify(`生成失败：${error.message}`, { error: true, timeout: 10000 });
  figma.closePlugin();
});
